import './Veiculo.css';
import carros from './carros';
import { useParams } from 'react-router-dom';


function Veiculo(props) {
    const { id } = useParams();
    const carro = carros.find((item) => item.id === parseInt(id));

    if (!carro) {
    return <h2>Carro não encontrado!</h2>;
  }

  return(
            <div className="col"> 
                <img
                    src={carro.imagem}
                    className= "bd-placeholder-img card-img-top" 
                    alt={carro.titulo}
                    width="50%" 
                    height="20"
                    style={{objectFit: "cover"}}
                />    


                         <p className="propriedades-veiculo"><b>{carro.titulo}</b></p> 
                         <p className="propriedades-veiculo"><b>R${props.preco}</b></p>
                 </div> 
  );
}

export default Veiculo;
